package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.text.StrBuilder#contains(char)
 */
public class StrBuilder_contains_TriageGen0Test {

    @Test
    public void testContains_CharExistsInMiddle() {
        StrBuilder sb = new StrBuilder("hello");
        assertTrue("Should return true when char is in the middle", sb.contains('e'));
        assertTrue("Should return true when char is in the middle", sb.contains('l'));
    }

    @Test
    public void testContains_CharExistsAtStart() {
        StrBuilder sb = new StrBuilder("apple");
        assertTrue("Should return true when char is at the start", sb.contains('a'));
    }

    @Test
    public void testContains_CharExistsAtEnd() {
        StrBuilder sb = new StrBuilder("apple");
        assertTrue("Should return true when char is at the end", sb.contains('e'));
    }

    @Test
    public void testContains_CharDoesNotExist() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse("Should return false when char is not present", sb.contains('z'));
    }

    @Test
    public void testContains_EmptyBuilder() {
        StrBuilder sb = new StrBuilder();
        assertFalse("Should return false for an empty builder", sb.contains('a'));
    }

    @Test
    public void testContains_SingleCharacterMatch() {
        StrBuilder sb = new StrBuilder("a");
        assertTrue("Should return true for single character match", sb.contains('a'));
        assertFalse("Should return false for single character mismatch", sb.contains('b'));
    }

    @Test
    public void testContains_SpecialCharacters() {
        StrBuilder sb = new StrBuilder(" \n\t!@#");
        assertTrue("Should handle whitespace", sb.contains(' '));
        assertTrue("Should handle newline", sb.contains('\n'));
        assertTrue("Should handle tab", sb.contains('\t'));
        assertTrue("Should handle special symbols", sb.contains('!'));
    }

    @Test
    public void testContains_CaseSensitivity() {
        StrBuilder sb = new StrBuilder("Java");
        assertTrue("Should find lowercase 'a'", sb.contains('a'));
        assertFalse("Should be case sensitive (not find 'A')", sb.contains('A'));
    }
}
